/* ObLark Sync: 暴露内部媒体解析器给 excalidraw-pdf-sync.js（只新增导出，不改变任何既有逻辑） */
module.exports.__oblarkInternals = { MediaHandler: nt };

/* ObLark Sync: 从真实插件目录加载 companion 扩展。
   Obsidian 桌面端用 eval/Function 包裹执行 main.js，其 require shim 会把相对路径
   ('./excalidraw-pdf-sync.js') 相对应用目录解析并 MODULE_NOT_FOUND。因此这里在
   module.exports.default 与 __oblarkInternals 就绪后，用 vault 路径 + createRequire
   从 <vault>/<configDir>/plugins/oblark-sync/ 定位并加载 Excalidraw sibling companion。 */
(function loadObLarkCompanions() {
	var pathMod = require("path");
	var moduleMod = require("module");
	var pluginDir;
	try {
		var vault = globalThis.app && globalThis.app.vault;
		if (!vault) throw new Error("globalThis.app.vault 不可用");
		var adapter = vault.adapter || {};
		var basePath = typeof adapter.getBasePath === "function" ? adapter.getBasePath() : adapter.basePath;
		if (!basePath) throw new Error("无法从 vault.adapter 获取 basePath");
		var configDir = vault.configDir || ".obsidian";
		pluginDir = pathMod.join(basePath, configDir, "plugins", "oblark-sync");
	} catch (error) {
		console.error("[ObLark Sync] 无法定位插件目录，companion 扩展未加载", error);
		return;
	}
	var companionRequire = moduleMod.createRequire(pathMod.join(pluginDir, "main.js"));
	var companions = [
		{ file: "excalidraw-pdf-sync.js", method: "scheduleExcalidrawPdfSyncInstall", label: "Excalidraw 图片同步扩展" },
		{ file: "push-error-reporter.js", method: "schedulePushErrorReporterInstall", label: "推送错误报告扩展" }
	];
	for (var i = 0; i < companions.length; i++) {
		var c = companions[i];
		var full = pathMod.join(pluginDir, c.file);
		try {
			if (companionRequire.cache) delete companionRequire.cache[full]; // 支持插件关闭后重载
			companionRequire(full)[c.method](module.exports);
		} catch (error) {
			console.error("[ObLark Sync] 加载" + c.label + "失败，插件目录: " + full, error);
		}
	}
})();
